createMap:
const host = document.createElement("div");
host.style.cssText = "width:240px;height:120px";
document.body.append(host);
const secondary = createMap(host, { center, zoom: 7, controls: false });
tileLayer(OSM, { renderer: "dom" }).addTo(secondary);
showResult(secondary.getCenter(), "Центр созданной карты");
setTimeout(() => { secondary.remove(); host.remove(); }, 2500);

featureGroup:
const group = featureGroup([
  marker(({ lat: 55.75, lng: 37.62 })).bindTooltip("Центр"),
  circle(({ lat: 55.75, lng: 37.62 }), 12000, { stroke: "#43d5c7", fillOpacity: 0.14 })
]).addTo(map);
map.fitBounds(group.getBounds(), { padding: 24 });
return group;

tileLayer:
const layer = tileLayer(OSM, { attribution: "© OpenStreetMap", renderer: "auto" }).addTo(map);
showResult(layer.getStats?.() ?? "Слой тайлов добавлен");
return layer;

geoJSON:
const layer = geoJSON(geojson, { renderer: "auto", style: () => ({ stroke: "#43d5c7", strokeWidth: 4, fillOpacity: .1 }) }).addTo(map);
map.fitBounds(layer.getBounds(), { padding: 30 });
return layer;

popup:
const overlay = popup("Standalone popup").setLatLng(center).openOn(map);
showResult("Popup открыт в центре карты");
return overlay;

customControl:
const button = document.createElement("button");
button.textContent = "Центр";
button.onclick = () => map.setView(center, 10);
return customControl(button, { position: "top-right" }).addTo(map);

objectManager:
const manager = objectManager({ clusterize: true, clusterRenderer: "auto" }).addTo(map);
await manager.addAsync(objects, { chunkSize: 250, yieldMode: "task", render: false });
manager.prepareLayout();
showResult(manager.getStats());
return manager;

spatialGridIndex:
const index = spatialGridIndex(1);
for (const item of objects) index.set(item.id, item.coordinates, item);
const visible = index.search(map.getBounds());
for (const item of visible.slice(0, 80)) circleMarker(item.value.coordinates, { radius: 3, fill: "#43d5c7", stroke: "transparent" }).addTo(map);
showResult({ indexed: index.size, visible: visible.length });
return index;

fromGeoJSONPosition:
const position = fromGeoJSONPosition([37.618423, 55.751244]);
marker(position).addTo(map);
showResult(position);
return position;

toGeoJSONPosition:
const coordinates = toGeoJSONPosition(center);
showResult(coordinates);
return coordinates;

searchProvider:
const provider = searchProvider([
  { name: "Москва", center },
  { name: "Зеленоград", center: ({ lat: 55.98, lng: 37.18 }) }
]);
const result = await provider.search("моск");
marker(result[0].center).bindPopup(result[0].name).addTo(map).openPopup();
showResult(result);
return provider;

createStraightLineRoutingProvider:
const provider = createStraightLineRoutingProvider();
const routes = await provider([{ latlng: ({ lat: 55.60, lng: 37.30 }) }, { latlng: ({ lat: 55.75, lng: 37.62 }) }, { latlng: ({ lat: 55.92, lng: 37.95 }) }], { alternatives: false, signal: new AbortController().signal });
polyline(routes[0].coordinates, { stroke: "#43d5c7", strokeWidth: 5 }).addTo(map);
showResult(routes[0]);
return provider;

routingLayer:
const layer = routingLayer({ provider: createStraightLineRoutingProvider() }).addTo(map);
await layer.route([({ lat: 55.60, lng: 37.30 }),({ lat: 55.75, lng: 37.62 }),({ lat: 55.92, lng: 37.95 })]);
return layer;

webglPointLayer:
const layer = webglPointLayer(points, { pointSize: 5, color: "#43d5c7" }).addTo(map);
showResult(layer.getStats());
return layer;

pathBatch:
const layer = pathBatch({ mode: "feature", interactive: true }).addTo(map);
layer.setPaths([
  { id: "main", positions: [({ lat: 55.55, lng: 37.2 }),({ lat: 55.75, lng: 37.62 }),({ lat: 55.95, lng: 38.05 })], style: { color: "#43d5c7", width: 5 } },
  { id: "alt", positions: [({ lat: 55.62, lng: 38.0 }),({ lat: 55.82, lng: 37.3 })], style: { color: "#ffd37a", width: 3, dashArray: [8, 4] } }
]);
return layer;

webglPolygonBatch:
const layer = webglPolygonBatch().addTo(map);
layer.setPolygons([{ rings: [[55.55,37.2, 55.55,38.0, 55.95,38.0, 55.95,37.2]], style: { fill: "#43d5c7", fillOpacity: .25 } }]);
return layer;

heatLayer:
const layer = heatLayer(weightedPoints, {
  mode: "both",
  backend: "auto",
  evaluation: "static",
  worker: true,
  labels: true,
  step: "auto",
  bands: true,
  cover: true,
  interactive: true
}).addTo(map);
await layer.rebuildAsync();
showResult(layer.getStats(), "Heat profile");
return layer;

buildHeat:
const result = await buildHeat(weightedPoints, demoBounds, {
  mode: "both",
  backend: "auto",
  cols: 320,
  rows: 240,
  step: "auto"
});
if (result) {
  const layer = heatLayer(weightedPoints, { mode: "both", cols: 320, rows: 240 }).addTo(map);
  await layer.rebuildAsync();
  showResult(result.profile, "Профиль buildHeat");
}
return result;

heatSupport:
const support = await heatSupport();
showResult(support, "Доступные backend");
return support;

preparePointBatch:
const packed = preparePointBatch(points);
webglPointLayer(points.slice(0, 800), { pointSize: 4, color: "#43d5c7" }).addTo(map);
showResult({ count: packed.count, skipped: packed.skipped });
return packed;

preparePointBatchAsync:
const packed = await preparePointBatchAsync(points, { chunkSize: 500, yieldMode: "task" });
webglPointLayer(points.slice(0, 800), { pointSize: 4, color: "#43d5c7" }).addTo(map);
showResult({ count: packed.count, skipped: packed.skipped });
return packed;

performanceInspector:
const inspector = performanceInspector(map);
await sleep(500);
showResult(inspector.snapshot(), "Performance snapshot");
return inspector;

resolveLocale:
const locale = resolveLocale("ru");
showResult(locale, "Русская локаль");
return locale;

bounds:
const result = bounds([({ lat: 55.55, lng: 37.20 }), ({ lat: 55.95, lng: 38.05 }), ({ lat: 55.72, lng: 38.18 })]);
rectangle(result, { stroke: "#70a7ff", fillOpacity: .08 }).addTo(map);
map.fitBounds(result, { padding: 30 });
return result;

geodesicInterpolate:
const route = geodesicInterpolate(({ lat: 55.75, lng: 37.62 }), ({ lat: 59.94, lng: 30.31 }), 80000);
polyline(route, { stroke: "#43d5c7", strokeWidth: 4 }).addTo(map);
map.fitBounds(route, { padding: 30 });
showResult({ vertices: route.length });
return route;

zoomForBounds:
const zoom = zoomForBounds({ width: 720, height: 480 }, demoBounds, 32, 18);
map.fitBounds(demoBounds, { padding: 32 });
showResult(zoom, "Рассчитанный zoom");
return zoom;

createWMTSFromCapabilities:
const xml = `<Capabilities><Contents><Layer><Identifier>basemap</Identifier><Style><Identifier>default</Identifier></Style><TileMatrixSet>EPSG:3857</TileMatrixSet><ResourceURL resourceType="tile" format="image/png" template="/tiles/{TileMatrix}/{TileCol}/{TileRow}.png"/></Layer></Contents></Capabilities>`;
const config = createWMTSFromCapabilities(xml);
showResult(config);
return config;

vectorTileLayer:
const layer = vectorTileLayer({ provider: () => geojson.features, style: () => ({ stroke: "#43d5c7", strokeWidth: 3, fillOpacity: .12 }) }).addTo(map);
showResult({ loadedTiles: layer.tiles.size });
return layer;

wmsTileLayer:
const layer = wmsTileLayer("https://example.test/wms", { layers: "temperature", format: "image/png", transparent: true });
showResult(layer.getTileUrl(0, 0, 0), "Сформированный WMS URL");
return layer;

wmtsTileLayer:
const layer = wmtsTileLayer("/tiles/{TileMatrix}/{TileCol}/{TileRow}.png", { layer: "basemap", tileMatrixSet: "EPSG:3857" });
showResult(layer.getTileUrl(1, 2, 3), "Сформированный WMTS URL");
return layer;

decodeMVT:
const features = decodeMVT(new Uint8Array(), { x: 0, y: 0, z: 0 });
showResult(features, "GeoJSON из пустого валидного tile");
return features;

icon:
const button = document.createElement("button");
button.textContent = "Открыть станцию";
const result = icon({ content: button, iconSize: [140, 36], iconAnchor: [70, 18] });
marker(center, { icon: result }).addTo(map);
return result;

sanitizeSvgElement:
const svg = new DOMParser().parseFromString('<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script><circle cx="20" cy="20" r="18" fill="#43d5c7"/></svg>', "image/svg+xml").documentElement;
const safe = sanitizeSvgElement(svg);
showResult(safe.outerHTML, "Очищенный SVG");
return safe;

videoOverlay:
const layer = videoOverlay("data:video/mp4;base64,", demoBounds, { autoplay: false, muted: true });
showResult("VideoOverlay создан; addTo(map) начнёт загрузку указанного видео");
return layer;

createSuggestWidget:
const host = document.createElement("div");
host.style.cssText = "position:absolute;z-index:1200;top:12px;right:12px;background:white;padding:8px";
const input = document.createElement("input");
input.value = "мо";
host.append(input);
document.body.append(host);
const provider = createSuggestProvider(async query => [`Москва · ${query}`, `Можайск · ${query}`], { debounceMs: 0 });
const widget = createSuggestWidget({ input, provider, label: item => item }).attach();
await sleep(50);
return widget;

trafficLayer:
const layer = trafficLayer("/assets/brand/png/orihon-mark-192.png", { dataTime: new Date(), opacity: .45 });
showResult({ state: layer.getState(), dataTime: layer.getDataTime() });
return layer;

createMapAdapter:
const host = document.createElement("div");
host.style.cssText = "position:absolute;width:220px;height:130px;right:12px;bottom:12px;z-index:900";
document.body.append(host);
const adapter = createMapAdapter(host, { center, zoom: 7, controls: false });
tileLayer(OSM, { renderer: "dom" }).addTo(adapter.map);
adapter.update({ zoom: 8 });
setTimeout(() => { adapter.destroy(); host.remove(); }, 2500);
return adapter;
